INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(62397, 0, 0, 'Your defiance of the Empress ends here!', 14, 0, 100, 0, 0, 30335, 'MELJARAK_INTRO'),
(62397, 1, 0, 'All of Pandaria will fall beneath the Wings of the Empress!', 14, 0, 100, 0, 0, 30336, 'MELJARAK_AGGRO'),
(62397, 2, 0, 'The Empress commands it!', 14, 0, 100, 0, 0, 30338, 'MELJARAK_SLAY'),
(62397, 3, 0, 'Empress... I have... failed you...', 14, 0, 100, 0, 0, 30337, 'MELJARAK_DEATH'),
(62397, 4, 0, 'My blade never misses its mark!', 14, 0, 100, 0, 0, 30340, 'MELJARAK_WHIRLING_BLADE'),
(62397, 5, 0, 'The skies belong to the Empress!', 14, 0, 100, 0, 0, 30341, 'MELJARAK_RAIN_BLADES'),
(62397, 6, 0, 'You fight like cowards!', 14, 0, 100, 0, 0, 30333, 'MELJARAK_WATCHFULL_EYE'),
(62397, 7, 0, 'To die for the empress is an honor!', 14, 0, 100, 0, 0, 30345, 'MELJARAK_GROUP_DIE_1'),
(62397, 7, 1, 'The wings of the empress cannot fail!', 14, 0, 100, 0, 0, 30346, 'MELJARAK_GROUP_DIE_2'),
(62397, 7, 2, 'You will pay for your transgressions!', 14, 0, 100, 0, 0, 30347, 'MELJARAK_GROUP_DIE_3');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(62511, 0, 0, 'Ah, I see you have found a few of my experiments.  Step closer, and you may witness the full glory of my work here.', 14, 0, 100, 0, 0, 31559, 'UNSOK_INTRO'),
(62511, 1, 0, 'You must be powerful, to have come this far. Yes, yes... you will make worthy test subjects.', 14, 0, 100, 0, 0, 31555, 'UNSOK_AGGRO'),
(62511, 2, 0, 'Watch your step!', 14, 0, 100, 0, 0, 31563, 'UNSOK_SPELL_AMBER_SCALPEL'),
(62511, 3, 0, 'Feel fortunate to receive this gift.', 14, 0, 100, 0, 0, 31562, 'UNSOK_SPELL_PARASITIC'),
(62511, 4, 0, 'From death comes life, and from life, death....', 14, 0, 100, 0, 0, 31564, 'UNSOK_SPELL_ABOMINATION'),
(62511, 5, 0, 'You must think yourselves mighty. How little you know. Behold now, my greatest creation!', 14, 0, 100, 0, 0, 31557, 'UNSOK_PHASE_2'),
(62511, 6, 0, 'What have you done? No, this will not be how my work ends. I will not allow it!', 14, 0, 100, 0, 0, 31558, 'UNSOK_PHASE_3'),
(62511, 7, 0, 'Excellent!', 14, 0, 100, 0, 0, 31561, 'UNSOK_SLAY'),
(62511, 8, 0, 'Forgive me, Empress....', 14, 0, 100, 0, 0, 31556, 'UNSOK_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(62543, 0, 0, 'They approach? Good. Now, if only my students were here to see and learn from the coming display of martial prowess...', 14, 0, 100, 0, 0, 29258, 'Tayak Intro'),
(62543, 1, 0, 'On your guard, invaders. I, Ta\'yak, Lord of Blades, will be your opponent.', 14, 0, 100, 0, 0, 29252, 'Tayak Intro'),
(62543, 2, 0, 'I\'d always hoped to cut someone like that someday, to hear that sound. But to have it happen to my own prothorax is ridiculous.', 14, 0, 100, 0, 0, 29253, 'Tayak Death'),
(62543, 3, 0, 'A perfect cut.', 14, 0, 100, 0, 0, 29259, 'Tayak Kill'),
(62543, 3, 1, 'This is the technique of a Blade Lord.', 14, 0, 100, 0, 0, 29260, 'Tayak Kill 2'),
(62543, 4, 0, 'Mere initiates.', 14, 0, 100, 0, 0, 29254, 'Tayak - 1'),
(62543, 4, 1, 'They should have studied harder.', 14, 0, 100, 0, 0, 29255, 'Tayak - 2'),
(62543, 4, 2, 'One technique alone is not enough.', 14, 0, 100, 0, 0, 29256, 'Tayak - 3'),
(62543, 4, 3, 'They failed their test. Will you?', 14, 0, 100, 0, 0, 29257, 'Tayak - 4'),
(62543, 5, 0, 'Can you follow my blade?', 14, 0, 100, 0, 0, 29261, 'Tayak - Heroic Spell'),
(62543, 6, 0, 'Now go, impart my techniques to the initiates.', 14, 0, 100, 0, 0, 0, 'Tayak - Intro'),
(62543, 7, 0, 'Blade Lord Ta\'yak marks $n for |cFFFF0000|Hspell:122949|h[Unseen Strike]|h|r!', 41, 0, 100, 0, 0, 0, 'Tayak- Strike Announce');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(62711, 0, 0, 'Fa... ther....', 14, 0, 100, 0, 0, 29238, 'MONSTROSITY_DEATH'),
(62711, 1, 0, 'The Amber Monstrosity readies an |cFFFF0000|Hspell:122398|h[Amber Explosion]|h|r!', 41, 0, 100, 0, 0, 29240, 'MONSTROSITY_EXPLOSION');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(62837, 0, 0, 'Seal the gates! Bar the exits! Destroy these intruders!', 14, 0, 100, 0, 0, 29278, 'SHEKZEER_INTRO'),
(62837, 1, 0, 'Death to all who dare challenge my empire!', 14, 0, 100, 0, 0, 29283, 'SHEKZEER_AGGRO'),
(62837, 2, 0, 'Sing... yes! Sing in agony!', 14, 0, 100, 0, 0, 29281, 'SHEKZEER_CRY_OF_TERROR'),
(62837, 3, 0, 'Breathe no longer!', 14, 0, 100, 0, 0, 29280, 'SHEKZEER_SLAY_1'),
(62837, 3, 1, 'Taste defeat, stranger!', 14, 0, 100, 0, 0, 29279, 'SHEKZEER_SLAY_2'),
(62837, 4, 0, 'Power... I must have more power! Guards! Protect your empress!', 14, 0, 100, 0, 0, 29270, 'SHEKZEER_PHASE_2'),
(62837, 5, 0, 'Such is the fate of those who question authority.', 14, 0, 100, 0, 0, 29273, 'SHEKZEER_RESET'),
(62837, 6, 0, 'I will dispose of the outsiders.', 14, 0, 100, 0, 0, 29271, 'SHEKZEER_EVENT_RECHARGE'),
(62837, 7, 0, 'Augh... ah ... I...  have failed.', 14, 0, 100, 0, 0, 29268, 'SHEKZEER_DEATH');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(62980, 1, 0, 'The Divine chose us to give mortal voice to Her divine will. We are but the vessel that enacts Her will.', 14, 0, 100, 0, 0, 29301, 'Imperial Vizier Zor\'lok - TALK_AGGRO'),
(62980, 2, 0, 'We will not give in to the despair of the dark void. If Her will for us is to perish, then it shall be so.', 14, 0, 100, 0, 0, 29302, 'Imperial Vizier Zor\'lok - TALK_DEATH'),
(62980, 3, 0, 'We are the extension of our Empress\'s will.', 14, 0, 100, 0, 0, 29303, 'Imperial Vizier Zor\'lok - TALK_EVENT_IDLE_1A'),
(62980, 4, 0, 'Ours is but to serve in Her divine name.', 14, 0, 100, 0, 0, 29304, 'Imperial Vizier Zor\'lok - TALK_EVENT_IDLE_1B'),
(62980, 5, 0, 'Never to question, nor to contemplate; we simply act.', 14, 0, 100, 0, 0, 29305, 'Imperial Vizier Zor\'lok - TALK_EVENT_IDLE_1C'),
(62980, 6, 0, 'We fight, toil, and serve so that Her vision for us is made reality.', 14, 0, 100, 0, 0, 29306, 'Imperial Vizier Zor\'lok - TALK_EVENT_IDLE_2'),
(62980, 7, 0, 'Her happiness is our reward, her sorrow our failure.', 14, 0, 100, 0, 0, 29307, 'Imperial Vizier Zor\'lok - TALK_EVENT_IDLE_3'),
(62980, 8, 0, 'We will give our lives for the Empress without hesitation. She is the light, and without Her our lives will be lost to darkness.', 14, 0, 100, 0, 0, 29308, 'Imperial Vizier Zor\'lok - TALK_EVENT_IDLE_4'),
(62980, 9, 0, 'Her gifts are many, our gratitude immeasurable.', 14, 0, 100, 0, 0, 29309, 'Imperial Vizier Zor\'lok - TALK_EVENT_PHASE_1'),
(62980, 10, 0, 'She tests us. We will not disappoint Her.', 14, 0, 100, 0, 0, 29310, 'Imperial Vizier Zor\'lok - TALK_EVENT_PHASE_2'),
(62980, 11, 0, 'We are as unwavering as the amber that shapes our halls. With Her might we will vanquish all who dare intrude upon Her divine home.', 14, 0, 100, 0, 0, 29311, 'Imperial Vizier Zor\'lok - TALK_EVENT_PHASE_3'),
(62980, 12, 0, 'The chaff of the world tumbles across our doorstep, driven by fear; Her royal storm will whisk them away.', 14, 0, 100, 0, 0, 29312, 'Imperial Vizier Zor\'lok - TALK_EVENT_TRASH_A_COMBAT'),
(62980, 13, 0, 'They were clearly unworthy of Her divine embrace.', 14, 0, 100, 0, 0, 29313, 'Imperial Vizier Zor\'lok - TALK_EVENT_TRASH_A_DIES'),
(62980, 14, 0, 'They are but the waves crashing upon the mountain of Her divine will. They may rise again and again; but will accomplish nothing.', 14, 0, 100, 0, 0, 29314, 'Imperial Vizier Zor\'lok - TALK_EVENT_TRASH_B_COMBAT'),
(62980, 15, 0, 'We are unfazed. We will stand firm.', 14, 0, 100, 0, 0, 29315, 'Imperial Vizier Zor\'lok - TALK_EVENT_TRASH_B_DIES'),
(62980, 16, 0, 'The Divine challenges us to face these intruders.', 14, 0, 100, 0, 0, 29316, 'Imperial Vizier Zor\'lok - TALK_EVENT_TRASH_C_COMBAT'),
(62980, 17, 0, 'And so it falls to us, Her chosen voice.', 14, 0, 100, 0, 0, 29317, 'Imperial Vizier Zor\'lok - TALK_EVENT_TRASH_C_DIES'),
(62980, 18, 0, 'The Divine will not suffer your taint here, outsider.', 14, 0, 100, 0, 0, 29318, 'Imperial Vizier Zor\'lok - TALK_SLAY_01'),
(62980, 19, 0, 'Ours is but to serve; yours is but to die.', 14, 0, 100, 0, 0, 29319, 'Imperial Vizier Zor\'lok - TALK_SLAY_02'),
(62980, 20, 0, 'Behold the voice of Her divine wrath.', 14, 0, 100, 0, 0, 29320, 'Imperial Vizier Zor\'lok - TALK_EXHALE'),
(62980, 21, 0, 'Through the air we breathe, She strengthens our voice.', 14, 0, 100, 0, 0, 29321, 'Imperial Vizier Zor\'lok - TALK_INHALE'),
(62980, 22, 0, 'Her will is greater than us all. You will join us or you will perish.', 14, 0, 100, 0, 0, 29322, 'Imperial Vizier Zor\'lok - TALK_CONVERT'),
(62980, 23, 0, 'Our voice gives form to Her will.', 14, 0, 100, 0, 0, 29323, 'Imperial Vizier Zor\'lok - TALK_PITCH'),
(62980, 24, 0, 'Imperial Vizier Zor\'lok flies to one of his platforms!', 41, 0, 100, 0, 0, 0, 'Imperial Vizier Zor\'lok - TALK_FLY_ANN'),
(62980, 25, 0, 'Imperial Vizier Zor\'lok inhales the Pheromones of Zeal!', 41, 0, 100, 0, 0, 0, 'Imperial Vizier Zor\'lok - TALK_INHALE_ZEAL_ANN'),
(62980, 26, 0, '|TInterface\\Icons\\spell_druid_stamedingroar.blp:20|tImperial Vizier Zor\'lok |cFFFF0000|Hspell:122852|h[Inhales]|h|r a large breath!', 41, 0, 100, 0, 0, 0, 'Imperial Vizier Zor\'lok - TALK_INHALE_ANN'),
(62980, 27, 0, '|TInterface\\Icons\\spell_arcane_mindmastery.blp:20|tImperial Vizier Zor\'lok uses his voice to |cFFFF0000|Hspell:122740|h[Convert]|h|r members of the raid to fight on his side!', 41, 0, 100, 0, 0, 0, 'Imperial Vizier Zor\'lok - TALK_CONVERT_ANN'),
(62980, 28, 0, '|TInterface\\Icons\\warrior_disruptingshout.blp:20|tImperial Vizier Zor\'lok shouts with |cFFFF0000|Hspell:122713|h[Force and Verve]|h|r!', 41, 0, 100, 0, 0, 0, 'Imperial Vizier Zor\'lok - TALK_FORCE_AND_VERVE_ANN');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(63942, 0, 0, 'No more excuses, Empress! Eliminate these cretins or I will kill you myself!', 14, 0, 100, 0, 0, 32647, 'SHA_AGGRO'),
(63942, 1, 0, 'You must destroy these outsiders, empress! They have come to conquer your people!', 14, 0, 100, 0, 0, 32648, 'SHA_INTRO'),
(63942, 2, 0, 'USELESS! Fall limp and die before me, wretched insect. Your kind are worthless to me!', 14, 0, 100, 0, 0, 32645, 'SHA_SHEKZEER_DEFEAT_1'),
(63942, 3, 0, 'As for the rest of you, seek me if you dare. Like the others, you will all die screaming.', 14, 0, 100, 0, 0, 32646, 'SHA_SHEKZEER_DEFEAT_2');
INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(65501, 0, 0, 'Pitiful, wingless grubs. You step out into my domain, and I will hear your death screams as you plummet from this terrace!', 14, 0, 100, 0, 0, 30348, 'MELJARAK_INTRO_EVENT_1'),
(65501, 1, 0, 'Set\'thik, in formation! Show them who controls the winds of Pandaria!', 14, 0, 100, 0, 0, 30349, 'MELJARAK_INTRO_EVENT_2'),
(65501, 2, 0, 'Breath of the empress, bring mighty Garalon to us!', 14, 0, 100, 0, 0, 30350, 'MELJARAK_INTRO_EVENT_SUMMON_GARALON'),
(65501, 3, 0, 'Garalon, grind their bones to dust!', 14, 0, 100, 0, 0, 30351, 'MELJARAK_INTRO_EVENT_GARALON_COMBAT'),
(65501, 4, 0, 'Impossible! Sri\'thik, Zar\'thik, Kor\'thik, to the top of the terrace! We must defend the Empress!', 14, 0, 100, 0, 0, 30352, 'MELJARAK_INTRO_EVENT_GARALON_DEATH');
